{
  "vulnerable_symbols": [],
  "trigger": "在 Node.js 中，当 Object.prototype 已被污染且应用未显式设置 auth/baseURL 等配置时，axios 发起任意 HTTP 请求即读取污染值并注入 Authorization、改写目标或执行回调。",
  "preconditions": [
    "axios 运行在 Node.js 并使用 HTTP adapter（非浏览器 XHR/fetch 路径）",
    "同一进程中 Object.prototype 已被污染，且污染了 auth、baseURL、socketPath、beforeRedirect 或 insecureHTTPParser 中至少一个",
    "目标请求的 config 未显式设置被污染的属性，使其通过原型链读取",
    "axios 版本处于 1.0.0 至 1.15.1（当前 1.7.4 满足）"
  ],
  "exploit_evidence": [
    {
      "src": 0,
      "kind": "poc",
      "quote": "Includes the vendor-published proof of concept and mitigation guidance."
    }
  ],
  "fixed_version": "1.15.2",
  "summary_zh": "axios 1.7.4 若原型被污染，HTTP 请求会读取 auth 等配置，致凭据注入或请求劫持，升级 1.15.2。"
}
